CREATE DATABASE BD_BancoFisclase ON  PRIMARY (     NAME = 'BD_BancoFisclase_Data',     FILENAME = 'C:\SQLData\BD_BancoFisclase_Data.mdf',     SIZE = 20MB,     MAXSIZE = 100MB,     FILEGROWTH = 5MB ) LOG ON (     NAME = 'BD_BancoFisclase_Log',     FILENAME = 'C:\SQLData\BD_BancoFisclase_Log.ldf',     SIZE = 10MB,     MAXSIZE = 50MB,     FILEGROWTH = 5MB ); GO  USE BD_BancoFisclase --- ===================================================== --- Estructura de la base de datos (CREATE TABLE) --- ===================================================== -- Crear tabla Cliente con dirección normalizada CREATE TABLE Cliente (     cliente_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(100) NOT NULL,     email NVARCHAR(100) NOT NULL,     telefono NVARCHAR(20),     calle NVARCHAR(100),     numero NVARCHAR(20),     ciudad NVARCHAR(50),     estado_provincia NVARCHAR(50),     codigo_postal NVARCHAR(20),     pais NVARCHAR(50),     fecha_registro DATETIME DEFAULT GETDATE(),     activo BIT DEFAULT 1,     CONSTRAINT PK_Cliente PRIMARY KEY CLUSTERED (cliente_id),     CONSTRAINT UQ_Cliente_Email UNIQUE (email) );  -- Crear tabla TipoCuenta CREATE TABLE TipoCuenta (     tipo_cuenta_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(50) NOT NULL,     descripcion NVARCHAR(200),     CONSTRAINT PK_TipoCuenta PRIMARY KEY CLUSTERED (tipo_cuenta_id),     CONSTRAINT UQ_TipoCuenta_Nombre UNIQUE (nombre) );  -- Crear tabla Cuenta CREATE TABLE Cuenta (     cuenta_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     tipo_cuenta_id INT NOT NULL,     numero_cuenta NVARCHAR(20) NOT NULL,     saldo DECIMAL(18,2) NOT NULL DEFAULT 0,     fecha_apertura DATETIME DEFAULT GETDATE(),     activa BIT DEFAULT 1,     CONSTRAINT PK_Cuenta PRIMARY KEY CLUSTERED (cuenta_id),     CONSTRAINT FK_Cuenta_Cliente FOREIGN KEY (cliente_id)          REFERENCES Cliente(cliente_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT FK_Cuenta_TipoCuenta FOREIGN KEY (tipo_cuenta_id)          REFERENCES TipoCuenta(tipo_cuenta_id)         ON DELETE NO ACTION         ON UPDATE CASCADE,     CONSTRAINT UQ_Cuenta_Numero UNIQUE (numero_cuenta),     CONSTRAINT CK_Cuenta_SaldoNoNegativo CHECK (saldo >= 0) );  -- Crear tabla Usuario CREATE TABLE Usuario (     usuario_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     username NVARCHAR(50) NOT NULL,     password_hash NVARCHAR(64) NOT NULL,     salt NVARCHAR(32) NOT NULL,     intentos_fallidos INT DEFAULT 0,     bloqueado BIT DEFAULT 0,     fecha_creacion DATETIME DEFAULT GETDATE(),     fecha_ultimo_login DATETIME, 	es_admin BIT DEFAULT 0,     CONSTRAINT PK_Usuario PRIMARY KEY CLUSTERED (usuario_id),     CONSTRAINT FK_Usuario_Cliente FOREIGN KEY (cliente_id)          REFERENCES Cliente(cliente_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT UQ_Usuario_Username UNIQUE (username),     CONSTRAINT CK_Usuario_IntentosFallidos CHECK (intentos_fallidos >= 0) ); ALTER TABLE Usuario  ADD es_admin BIT DEFAULT 0;  -- Crear tabla de referencia TipoTransaccion CREATE TABLE TipoTransaccion (     tipo_transaccion_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(50) NOT NULL,     descripcion NVARCHAR(200),     CONSTRAINT PK_TipoTransaccion PRIMARY KEY CLUSTERED (tipo_transaccion_id),     CONSTRAINT UQ_TipoTransaccion_Nombre UNIQUE (nombre) );  -- Crear tabla de referencia EstadoTransaccion CREATE TABLE EstadoTransaccion (     estado_transaccion_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(20) NOT NULL,     descripcion NVARCHAR(100),     CONSTRAINT PK_EstadoTransaccion PRIMARY KEY CLUSTERED (estado_transaccion_id),     CONSTRAINT UQ_EstadoTransaccion_Nombre UNIQUE (nombre) );  -- Crear tabla Transaccion con referencias adecuadas CREATE TABLE Transaccion (     transaccion_id INT IDENTITY(1,1) NOT NULL,     tipo_transaccion_id INT NOT NULL,     estado_transaccion_id INT NOT NULL,     monto DECIMAL(18,2) NOT NULL,     descripcion NVARCHAR(200),     fecha DATETIME DEFAULT GETDATE(),     fecha_actualizacion DATETIME,     usuario_id INT, -- Quién inició la transacción 	cuenta_destino INT NULL     CONSTRAINT FK_Transaccion_CuentaDestino FOREIGN KEY (cuenta_destino)  		REFERENCES Cuenta(cuenta_id), 	cuenta_origen INT NULL     CONSTRAINT FK_Transaccion_CuentaOrigen FOREIGN KEY (cuenta_origen)  		REFERENCES Cuenta(cuenta_id),     CONSTRAINT PK_Transaccion PRIMARY KEY CLUSTERED (transaccion_id),     CONSTRAINT FK_Transaccion_TipoTransaccion FOREIGN KEY (tipo_transaccion_id)          REFERENCES TipoTransaccion(tipo_transaccion_id),     CONSTRAINT FK_Transaccion_EstadoTransaccion FOREIGN KEY (estado_transaccion_id)          REFERENCES EstadoTransaccion(estado_transaccion_id),     CONSTRAINT FK_Transaccion_Usuario FOREIGN KEY (usuario_id)          REFERENCES Usuario(usuario_id),     CONSTRAINT CK_Transaccion_MontoPositivo CHECK (monto > 0) );  -- Crear tabla Movimiento CREATE TABLE Movimiento (     movimiento_id INT IDENTITY(1,1) NOT NULL,     cuenta_id INT NOT NULL,     transaccion_id INT NOT NULL,     monto_debito DECIMAL(18,2) DEFAULT 0,     monto_credito DECIMAL(18,2) DEFAULT 0,     saldo_resultante DECIMAL(18,2) NOT NULL,     fecha DATETIME DEFAULT GETDATE(),     CONSTRAINT PK_Movimiento PRIMARY KEY CLUSTERED (movimiento_id),     CONSTRAINT FK_Movimiento_Cuenta FOREIGN KEY (cuenta_id)          REFERENCES Cuenta(cuenta_id)         ON DELETE NO ACTION         ON UPDATE CASCADE,     CONSTRAINT FK_Movimiento_Transaccion FOREIGN KEY (transaccion_id)          REFERENCES Transaccion(transaccion_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT CK_Movimiento_MontosNoNegativos CHECK (monto_debito >= 0 AND monto_credito >= 0),     CONSTRAINT CK_Movimiento_DebitoOCredito CHECK (         (monto_debito > 0 AND monto_credito = 0) OR          (monto_debito = 0 AND monto_credito > 0)     ) );  -- Crear tabla Notificacion para seguimiento de correos CREATE TABLE Notificacion (     notificacion_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     tipo NVARCHAR(50) NOT NULL, -- 'ResumenDiario', 'AlertaSeguridad', etc.     asunto NVARCHAR(200) NOT NULL,     contenido NVARCHAR(MAX),     fecha_envio DATETIME DEFAULT GETDATE(),     estado NVARCHAR(20) DEFAULT 'Enviada', -- 'Enviada', 'Fallida', 'Pendiente'     CONSTRAINT PK_Notificacion PRIMARY KEY CLUSTERED (notificacion_id),     CONSTRAINT FK_Notificacion_Cliente FOREIGN KEY (cliente_id)          REFERENCES Cliente(cliente_id) );  --- ===================================================== --- Inserción de datos iniciales (INSERT) --- ===================================================== -- Insertar tipos de cuenta INSERT INTO TipoCuenta (nombre, descripcion) VALUES  (N'AHORRO', N'Cuenta de ahorros personal'), (N'CORRIENTE', N'Cuenta corriente personal'), (N'CREDITO', N'Tarjeta de crédito'), (N'DEBITO', N'Tarjeta de débito');  -- Insertar tipos de transacción INSERT INTO TipoTransaccion (nombre, descripcion) VALUES  (N'TRANSFER_INTERNO', N'Transferencia entre cuentas del mismo cliente'), (N'TRANSFER_EXTERNO', N'Transferencia a cuentas de otros clientes'), (N'DEPOSITO', N'Depósito de efectivo'), (N'RETIRO', N'Retiro de efectivo');  -- Insertar estados de transacción (NUEVOS VALORES) INSERT INTO EstadoTransaccion (nombre, descripcion) VALUES  ('COMPLETADO', 'Transacción completada exitosamente'), ('RECHAZADO', 'Transacción rechazada'), ('PENDIENTE', 'Transacción pendiente de procesamiento');   --- ===================================================== --- Procedimientos Almacenados (CREATE OR ALTER PROCEDURE) --- =====================================================  CREATE OR ALTER PROCEDURE sp_LoginValidate     @username NVARCHAR(50),     @password NVARCHAR(100),     @loginSuccess BIT OUTPUT,     @isLocked BIT OUTPUT,     @cliente_id INT OUTPUT,     @message NVARCHAR(100) OUTPUT,     @es_admin BIT OUTPUT AS BEGIN     DECLARE @storedHash NVARCHAR(64)     DECLARE @salt NVARCHAR(32)     DECLARE @attempts INT     DECLARE @blocked BIT          -- Se inicializan los parámetros para evitar errores     SET @loginSuccess = 0     SET @isLocked = 0     SET @cliente_id = 0     SET @message = ''          -- Validar si existe el usuario con contraseña hash y salt     SELECT          @storedHash = password_hash,          @salt = salt,          @attempts = intentos_fallidos,          @blocked = bloqueado,         @cliente_id = cliente_id,         @es_admin = es_admin     FROM Usuario      WHERE username = @username          -- Para validar si el usuario no existe     IF @storedHash IS NULL     BEGIN         SET @message = 'Usuario no encontrado'         RETURN     END          -- Validar si la cuenta está bloqueada.     IF @blocked = 1     BEGIN         SET @isLocked = 1         SET @message = 'Cuenta bloqueada. Contacte al administrador.'         RETURN     END          -- Calcula la contraseña hash con el salt (compatibilidad hex/base64)     DECLARE @inputHashBin VARBINARY(32);     DECLARE @inputHashHex NVARCHAR(64);     DECLARE @inputHashBase64 NVARCHAR(80);      SET @inputHashBin = HASHBYTES('SHA2_256', CONCAT(@password, @salt));     -- hex string (lowercase, without 0x)     SET @inputHashHex = LOWER(SUBSTRING(master.dbo.fn_varbintohexstr(@inputHashBin), 3, 8000));     -- base64 representation     SET @inputHashBase64 = CAST(N'' AS XML).value('xs:base64Binary(sql:variable("@inputHashBin"))', 'VARCHAR(80)');      -- Comparar hash: si el storedHash tiene 64 caracteres se asume hex, si no se compara con base64     IF (LEN(@storedHash) = 64)     BEGIN         IF LOWER(@storedHash) = @inputHashHex         BEGIN             -- Login exitoso             SET @loginSuccess = 1             SET @message = 'Login exitoso'                          -- Reinicia los intentos fallidos a 0 y registra la fecha del último login             UPDATE Usuario              SET intentos_fallidos = 0,                 fecha_ultimo_login = GETDATE()             WHERE username = @username         END         ELSE         BEGIN             -- Login fallido             SET @message = 'Credenciales incorrectas'                          -- Incrementar intentos fallidos             UPDATE Usuario              SET intentos_fallidos = intentos_fallidos + 1             WHERE username = @username                          -- Validar si la cuenta debería estar bloqueada             IF (SELECT intentos_fallidos FROM Usuario WHERE username = @username) >= 3             BEGIN                 UPDATE Usuario                  SET bloqueado = 1                 WHERE username = @username                                  SET @isLocked = 1                 SET @message = 'Cuenta bloqueada por demasiados intentos fallidos'             END         END     END     ELSE     BEGIN         -- tratar como base64         IF @storedHash = @inputHashBase64         BEGIN             -- Login exitoso             SET @loginSuccess = 1             SET @message = 'Login exitoso'                          -- Reinicia los intentos fallidos a 0 y registra la fecha del último login             UPDATE Usuario              SET intentos_fallidos = 0,                 fecha_ultimo_login = GETDATE()             WHERE username = @username         END         ELSE         BEGIN             -- Login fallido             SET @message = 'Credenciales incorrectas'                          -- Incrementar intentos fallidos             UPDATE Usuario              SET intentos_fallidos = intentos_fallidos + 1             WHERE username = @username                          -- Validar si la cuenta debería estar bloqueada             IF (SELECT intentos_fallidos FROM Usuario WHERE username = @username) >= 3             BEGIN                 UPDATE Usuario                  SET bloqueado = 1                 WHERE username = @username                                  SET @isLocked = 1                 SET @message = 'Cuenta bloqueada por demasiados intentos fallidos'             END         END     END END; GO  -- ================================================================================== -- Script adicional (para ejecución manual en entorno de pruebas): -- Reestablece la contraseña de todos los usuarios a 'password123', genera salt (base64) -- y almacena el hash SHA-256 como cadena hex de 64 caracteres (matching .NET ComputeSha256Hex) -- WARNING: Run only in a test environment. -- ==================================================================================  -- Example usage: execute this block to reset test passwords IF 1 = 0 BEGIN     DECLARE @pwd NVARCHAR(100) = N'password123';     DECLARE @id INT;     DECLARE @salt_bin VARBINARY(16);     DECLARE @salt_b64 NVARCHAR(80);     DECLARE @hash_bin VARBINARY(32);     DECLARE @hash_hex NVARCHAR(64);      DECLARE cur CURSOR LOCAL FAST_FORWARD FOR         SELECT usuario_id FROM Usuario;      OPEN cur;     FETCH NEXT FROM cur INTO @id;     WHILE @@FETCH_STATUS = 0     BEGIN         SET @salt_bin = CRYPT_GEN_RANDOM(16);         SET @salt_b64 = CAST(N'' AS XML).value('xs:base64Binary(sql:variable("@salt_bin"))', 'VARCHAR(80)');          SET @hash_bin = HASHBYTES('SHA2_256', CONCAT(@pwd, @salt_b64));         SET @hash_hex = LOWER(SUBSTRING(master.dbo.fn_varbintohexstr(@hash_bin), 3, 8000));          UPDATE Usuario         SET password_hash = @hash_hex,             salt = @salt_b64,             intentos_fallidos = 0,             bloqueado = 0         WHERE usuario_id = @id;          FETCH NEXT FROM cur INTO @id;     END      CLOSE cur;     DEALLOCATE cur; END  -- ================================================================================== -- Fin de script adicional -- ==================================================================================  -- Crear tabla Cliente con dirección normalizada CREATE TABLE Cliente (     cliente_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(100) NOT NULL,     email NVARCHAR(100) NOT NULL,     telefono NVARCHAR(20),     calle NVARCHAR(100),     numero NVARCHAR(20),     ciudad NVARCHAR(50),     estado_provincia NVARCHAR(50),     codigo_postal NVARCHAR(20),     pais NVARCHAR(50),     fecha_registro DATETIME DEFAULT GETDATE(),     activo BIT DEFAULT 1,     CONSTRAINT PK_Cliente PRIMARY KEY CLUSTERED (cliente_id),     CONSTRAINT UQ_Cliente_Email UNIQUE (email) );  -- Crear tabla TipoCuenta CREATE TABLE TipoCuenta (     tipo_cuenta_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(50) NOT NULL,     descripcion NVARCHAR(200),     CONSTRAINT PK_TipoCuenta PRIMARY KEY CLUSTERED (tipo_cuenta_id),     CONSTRAINT UQ_TipoCuenta_Nombre UNIQUE (nombre) );  -- Crear tabla Cuenta CREATE TABLE Cuenta (     cuenta_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     tipo_cuenta_id INT NOT NULL,     numero_cuenta NVARCHAR(20) NOT NULL,     saldo DECIMAL(18,2) NOT NULL DEFAULT 0,     fecha_apertura DATETIME DEFAULT GETDATE(),     activa BIT DEFAULT 1,     CONSTRAINT PK_Cuenta PRIMARY KEY CLUSTERED (cuenta_id),     CONSTRAINT FK_Cuenta_Cliente FOREIGN KEY (cliente_id)         REFERENCES Cliente(cliente_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT FK_Cuenta_TipoCuenta FOREIGN KEY (tipo_cuenta_id)         REFERENCES TipoCuenta(tipo_cuenta_id)         ON DELETE NO ACTION         ON UPDATE CASCADE,     CONSTRAINT UQ_Cuenta_Numero UNIQUE (numero_cuenta),     CONSTRAINT CK_Cuenta_SaldoNoNegativo CHECK (saldo >= 0) );  -- Crear tabla Usuario CREATE TABLE Usuario (     usuario_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     username NVARCHAR(50) NOT NULL,     password_hash NVARCHAR(64) NOT NULL,     salt NVARCHAR(32) NOT NULL,     intentos_fallidos INT DEFAULT 0,     bloqueado BIT DEFAULT 0,     fecha_creacion DATETIME DEFAULT GETDATE(),     fecha_ultimo_login DATETIME, 	es_admin BIT DEFAULT 0,     CONSTRAINT PK_Usuario PRIMARY KEY CLUSTERED (usuario_id),     CONSTRAINT FK_Usuario_Cliente FOREIGN KEY (cliente_id)         REFERENCES Cliente(cliente_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT UQ_Usuario_Username UNIQUE (username),     CONSTRAINT CK_Usuario_IntentosFallidos CHECK (intentos_fallidos >= 0) ); ALTER TABLE Usuario  ADD es_admin BIT DEFAULT 0;  -- Crear tabla de referencia TipoTransaccion CREATE TABLE TipoTransaccion (     tipo_transaccion_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(50) NOT NULL,     descripcion NVARCHAR(200),     CONSTRAINT PK_TipoTransaccion PRIMARY KEY CLUSTERED (tipo_transaccion_id),     CONSTRAINT UQ_TipoTransaccion_Nombre UNIQUE (nombre) );  -- Crear tabla de referencia EstadoTransaccion CREATE TABLE EstadoTransaccion (     estado_transaccion_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(20) NOT NULL,     descripcion NVARCHAR(100),     CONSTRAINT PK_EstadoTransaccion PRIMARY KEY CLUSTERED (estado_transaccion_id),     CONSTRAINT UQ_EstadoTransaccion_Nombre UNIQUE (nombre) );  -- Crear tabla Transaccion con referencias adecuadas CREATE TABLE Transaccion (     transaccion_id INT IDENTITY(1,1) NOT NULL,     tipo_transaccion_id INT NOT NULL,     estado_transaccion_id INT NOT NULL,     monto DECIMAL(18,2) NOT NULL,     descripcion NVARCHAR(200),     fecha DATETIME DEFAULT GETDATE(),     fecha_actualizacion DATETIME,     usuario_id INT, -- Quién inició la transacción 	cuenta_destino INT NULL     CONSTRAINT FK_Transaccion_CuentaDestino FOREIGN KEY (cuenta_destino) 		REFERENCES Cuenta(cuenta_id), 	cuenta_origen INT NULL     CONSTRAINT FK_Transaccion_CuentaOrigen FOREIGN KEY (cuenta_origen) 		REFERENCES Cuenta(cuenta_id),     CONSTRAINT PK_Transaccion PRIMARY KEY CLUSTERED (transaccion_id),     CONSTRAINT FK_Transaccion_TipoTransaccion FOREIGN KEY (tipo_transaccion_id)         REFERENCES TipoTransaccion(tipo_transaccion_id),     CONSTRAINT FK_Transaccion_EstadoTransaccion FOREIGN KEY (estado_transaccion_id)         REFERENCES EstadoTransaccion(estado_transaccion_id),     CONSTRAINT FK_Transaccion_Usuario FOREIGN KEY (usuario_id)         REFERENCES Usuario(usuario_id),     CONSTRAINT CK_Transaccion_MontoPositivo CHECK (monto > 0) );  -- Crear tabla Movimiento CREATE TABLE Movimiento (     movimiento_id INT IDENTITY(1,1) NOT NULL,     cuenta_id INT NOT NULL,     transaccion_id INT NOT NULL,     monto_debito DECIMAL(18,2) DEFAULT 0,     monto_credito DECIMAL(18,2) DEFAULT 0,     saldo_resultante DECIMAL(18,2) NOT NULL,     fecha DATETIME DEFAULT GETDATE(),     CONSTRAINT PK_Movimiento PRIMARY KEY CLUSTERED (movimiento_id),     CONSTRAINT FK_Movimiento_Cuenta FOREIGN KEY (cuenta_id)         REFERENCES Cuenta(cuenta_id)         ON DELETE NO ACTION         ON UPDATE CASCADE,     CONSTRAINT FK_Movimiento_Transaccion FOREIGN KEY (transaccion_id)         REFERENCES Transaccion(transaccion_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT CK_Movimiento_MontosNoNegativos CHECK (monto_debito >= 0 AND monto_credito >= 0),     CONSTRAINT CK_Movimiento_DebitoOCredito CHECK (         (monto_debito > 0 AND monto_credito = 0) OR         (monto_debito = 0 AND monto_credito > 0)     ) );  -- Crear tabla Notificacion para seguimiento de correos CREATE TABLE Notificacion (     notificacion_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     tipo NVARCHAR(50) NOT NULL, -- 'ResumenDiario', 'AlertaSeguridad', etc.     asunto NVARCHAR(200) NOT NULL,     contenido NVARCHAR(MAX),     fecha_envio DATETIME DEFAULT GETDATE(),     estado NVARCHAR(20) DEFAULT 'Enviada', -- 'Enviada', 'Fallida', 'Pendiente'     CONSTRAINT PK_Notificacion PRIMARY KEY CLUSTERED (notificacion_id),     CONSTRAINT FK_Notificacion_Cliente FOREIGN KEY (cliente_id)         REFERENCES Cliente(cliente_id) );  --- ===================================================== --- Inserción de datos iniciales (INSERT) --- ===================================================== -- Insertar tipos de cuenta INSERT INTO TipoCuenta (nombre, descripcion) VALUES  (N'AHORRO', N'Cuenta de ahorros personal'), (N'CORRIENTE', N'Cuenta corriente personal'), (N'CREDITO', N'Tarjeta de crédito'), (N'DEBITO', N'Tarjeta de débito');  -- Insertar tipos de transacción INSERT INTO TipoTransaccion (nombre, descripcion) VALUES  (N'TRANSFER_INTERNO', N'Transferencia entre cuentas del mismo cliente'), (N'TRANSFER_EXTERNO', N'Transferencia a cuentas de otros clientes'), (N'DEPOSITO', N'Depósito de efectivo'), (N'RETIRO', N'Retiro de efectivo');  -- Insertar estados de transacción (NUEVOS VALORES) INSERT INTO EstadoTransaccion (nombre, descripcion) VALUES  ('COMPLETADO', 'Transacción completada exitosamente'), ('RECHAZADO', 'Transacción rechazada'), ('PENDIENTE', 'Transacción pendiente de procesamiento');    --- ===================================================== --- Procedimientos Almacenados (CREATE OR ALTER PROCEDURE) --- =====================================================  CREATE OR ALTER PROCEDURE sp_LoginValidate     @username NVARCHAR(50),     @password NVARCHAR(100),     @loginSuccess BIT OUTPUT,     @isLocked BIT OUTPUT,     @cliente_id INT OUTPUT,     @message NVARCHAR(100) OUTPUT,     @es_admin BIT OUTPUT AS BEGIN     DECLARE @storedHash NVARCHAR(64)     DECLARE @salt NVARCHAR(32)     DECLARE @attempts INT     DECLARE @blocked BIT          -- Se inicializan los parámetros para evitar errores     SET @loginSuccess = 0     SET @isLocked = 0     SET @cliente_id = 0     SET @message = ''          -- Validar si existe el usuario con contraseña hash y salt     SELECT          @storedHash = password_hash,          @salt = salt,          @attempts = intentos_fallidos,          @blocked = bloqueado,         @cliente_id = cliente_id,         @es_admin = es_admin     FROM Usuario      WHERE username = @username          -- Para validar si el usuario no existe     IF @storedHash IS NULL     BEGIN         SET @message = 'Usuario no encontrado'         RETURN     END          -- Validar si la cuenta está bloqueada.     IF @blocked = 1     BEGIN         SET @isLocked = 1         SET @message = 'Cuenta bloqueada. Contacte al administrador.'         RETURN     END          -- Calcula la contraseña hash con el salt (compatibilidad hex/base64)     DECLARE @inputHashBin VARBINARY(32);     DECLARE @inputHashHex NVARCHAR(64);     DECLARE @inputHashBase64 NVARCHAR(80);      SET @inputHashBin = HASHBYTES('SHA2_256', CONCAT(@password, @salt));     -- hex string (lowercase, without 0x)     SET @inputHashHex = LOWER(SUBSTRING(master.dbo.fn_varbintohexstr(@inputHashBin), 3, 8000));     -- base64 representation     SET @inputHashBase64 = CAST(N'' AS XML).value('xs:base64Binary(sql:variable("@inputHashBin"))', 'VARCHAR(80)');      -- Comparar hash: si el storedHash tiene 64 caracteres se asume hex, si no se compara con base64     IF (LEN(@storedHash) = 64)     BEGIN         IF LOWER(@storedHash) = @inputHashHex         BEGIN             -- Login exitoso             SET @loginSuccess = 1             SET @message = 'Login exitoso'                          -- Reinicia los intentos fallidos a 0 y registra la fecha del último login             UPDATE Usuario              SET intentos_fallidos = 0,                 fecha_ultimo_login = GETDATE()             WHERE username = @username         END         ELSE         BEGIN             -- Login fallido             SET @message = 'Credenciales incorrectas'                          -- Incrementar intentos fallidos             UPDATE Usuario              SET intentos_fallidos = intentos_fallidos + 1             WHERE username = @username                          -- Validar si la cuenta debería estar bloqueada             IF (SELECT intentos_fallidos FROM Usuario WHERE username = @username) >= 3             BEGIN                 UPDATE Usuario                  SET bloqueado = 1                 WHERE username = @username                                  SET @isLocked = 1                 SET @message = 'Cuenta bloqueada por demasiados intentos fallidos'             END         END     END     ELSE     BEGIN         -- tratar como base64         IF @storedHash = @inputHashBase64         BEGIN             -- Login exitoso             SET @loginSuccess = 1             SET @message = 'Login exitoso'                          -- Reinicia los intentos fallidos a 0 y registra la fecha del último login             UPDATE Usuario              SET intentos_fallidos = 0,                 fecha_ultimo_login = GETDATE()             WHERE username = @username         END         ELSE         BEGIN             -- Login fallido             SET @message = 'Credenciales incorrectas'                          -- Incrementar intentos fallidos             UPDATE Usuario              SET intentos_fallidos = intentos_fallidos + 1             WHERE username = @username                          -- Validar si la cuenta debería estar bloqueada             IF (SELECT intentos_fallidos FROM Usuario WHERE username = @username) >= 3             BEGIN                 UPDATE Usuario                  SET bloqueado = 1                 WHERE username = @username                                  SET @isLocked = 1                 SET @message = 'Cuenta bloqueada por demasiados intentos fallidos'             END         END     END END; GO  -- ================================================================================== -- Script adicional (para ejecución manual en entorno de pruebas): -- Reestablece la contraseña de todos los usuarios a 'password123', genera salt (base64) -- y almacena el hash SHA-256 como cadena hex de 64 caracteres (matching .NET ComputeSha256Hex) -- WARNING: Run only in a test environment. -- ==================================================================================  -- Example usage: execute this block to reset test passwords IF 1 = 0 BEGIN     DECLARE @pwd NVARCHAR(100) = N'password123';     DECLARE @id INT;     DECLARE @salt_bin VARBINARY(16);     DECLARE @salt_b64 NVARCHAR(80);     DECLARE @hash_bin VARBINARY(32);     DECLARE @hash_hex NVARCHAR(64);      DECLARE cur CURSOR LOCAL FAST_FORWARD FOR         SELECT usuario_id FROM Usuario;      OPEN cur;     FETCH NEXT FROM cur INTO @id;     WHILE @@FETCH_STATUS = 0     BEGIN         SET @salt_bin = CRYPT_GEN_RANDOM(16);         SET @salt_b64 = CAST(N'' AS XML).value('xs:base64Binary(sql:variable("@salt_bin"))', 'VARCHAR(80)');          SET @hash_bin = HASHBYTES('SHA2_256', CONCAT(@pwd, @salt_b64));         SET @hash_hex = LOWER(SUBSTRING(master.dbo.fn_varbintohexstr(@hash_bin), 3, 8000));          UPDATE Usuario         SET password_hash = @hash_hex,             salt = @salt_b64,             intentos_fallidos = 0,             bloqueado = 0         WHERE usuario_id = @id;          FETCH NEXT FROM cur INTO @id;     END      CLOSE cur;     DEALLOCATE cur; END  -- ================================================================================== -- Fin de script adicional -- ==================================================================================  -- Crear tabla Cliente con dirección normalizada CREATE TABLE Cliente (     cliente_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(100) NOT NULL,     email NVARCHAR(100) NOT NULL,     telefono NVARCHAR(20),     calle NVARCHAR(100),     numero NVARCHAR(20),     ciudad NVARCHAR(50),     estado_provincia NVARCHAR(50),     codigo_postal NVARCHAR(20),     pais NVARCHAR(50),     fecha_registro DATETIME DEFAULT GETDATE(),     activo BIT DEFAULT 1,     CONSTRAINT PK_Cliente PRIMARY KEY CLUSTERED (cliente_id),     CONSTRAINT UQ_Cliente_Email UNIQUE (email) );  -- Crear tabla TipoCuenta CREATE TABLE TipoCuenta (     tipo_cuenta_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(50) NOT NULL,     descripcion NVARCHAR(200),     CONSTRAINT PK_TipoCuenta PRIMARY KEY CLUSTERED (tipo_cuenta_id),     CONSTRAINT UQ_TipoCuenta_Nombre UNIQUE (nombre) );  -- Crear tabla Cuenta CREATE TABLE Cuenta (     cuenta_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     tipo_cuenta_id INT NOT NULL,     numero_cuenta NVARCHAR(20) NOT NULL,     saldo DECIMAL(18,2) NOT NULL DEFAULT 0,     fecha_apertura DATETIME DEFAULT GETDATE(),     activa BIT DEFAULT 1,     CONSTRAINT PK_Cuenta PRIMARY KEY CLUSTERED (cuenta_id),     CONSTRAINT FK_Cuenta_Cliente FOREIGN KEY (cliente_id)         REFERENCES Cliente(cliente_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT FK_Cuenta_TipoCuenta FOREIGN KEY (tipo_cuenta_id)         REFERENCES TipoCuenta(tipo_cuenta_id)         ON DELETE NO ACTION         ON UPDATE CASCADE,     CONSTRAINT UQ_Cuenta_Numero UNIQUE (numero_cuenta),     CONSTRAINT CK_Cuenta_SaldoNoNegativo CHECK (saldo >= 0) );  -- Crear tabla Usuario CREATE TABLE Usuario (     usuario_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     username NVARCHAR(50) NOT NULL,     password_hash NVARCHAR(64) NOT NULL,     salt NVARCHAR(32) NOT NULL,     intentos_fallidos INT DEFAULT 0,     bloqueado BIT DEFAULT 0,     fecha_creacion DATETIME DEFAULT GETDATE(),     fecha_ultimo_login DATETIME, 	es_admin BIT DEFAULT 0,     CONSTRAINT PK_Usuario PRIMARY KEY CLUSTERED (usuario_id),     CONSTRAINT FK_Usuario_Cliente FOREIGN KEY (cliente_id)         REFERENCES Cliente(cliente_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT UQ_Usuario_Username UNIQUE (username),     CONSTRAINT CK_Usuario_IntentosFallidos CHECK (intentos_fallidos >= 0) ); ALTER TABLE Usuario  ADD es_admin BIT DEFAULT 0;  -- Crear tabla de referencia TipoTransaccion CREATE TABLE TipoTransaccion (     tipo_transaccion_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(50) NOT NULL,     descripcion NVARCHAR(200),     CONSTRAINT PK_TipoTransaccion PRIMARY KEY CLUSTERED (tipo_transaccion_id),     CONSTRAINT UQ_TipoTransaccion_Nombre UNIQUE (nombre) );  -- Crear tabla de referencia EstadoTransaccion CREATE TABLE EstadoTransaccion (     estado_transaccion_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(20) NOT NULL,     descripcion NVARCHAR(100),     CONSTRAINT PK_EstadoTransaccion PRIMARY KEY CLUSTERED (estado_transaccion_id),     CONSTRAINT UQ_EstadoTransaccion_Nombre UNIQUE (nombre) );  -- Crear tabla Transaccion con referencias adecuadas CREATE TABLE Transaccion (     transaccion_id INT IDENTITY(1,1) NOT NULL,     tipo_transaccion_id INT NOT NULL,     estado_transaccion_id INT NOT NULL,     monto DECIMAL(18,2) NOT NULL,     descripcion NVARCHAR(200),     fecha DATETIME DEFAULT GETDATE(),     fecha_actualizacion DATETIME,     usuario_id INT, -- Quién inició la transacción 	cuenta_destino INT NULL     CONSTRAINT FK_Transaccion_CuentaDestino FOREIGN KEY (cuenta_destino) 		REFERENCES Cuenta(cuenta_id), 	cuenta_origen INT NULL     CONSTRAINT FK_Transaccion_CuentaOrigen FOREIGN KEY (cuenta_origen) 		REFERENCES Cuenta(cuenta_id),     CONSTRAINT PK_Transaccion PRIMARY KEY CLUSTERED (transaccion_id),     CONSTRAINT FK_Transaccion_TipoTransaccion FOREIGN KEY (tipo_transaccion_id)         REFERENCES TipoTransaccion(tipo_transaccion_id),     CONSTRAINT FK_Transaccion_EstadoTransaccion FOREIGN KEY (estado_transaccion_id)         REFERENCES EstadoTransaccion(estado_transaccion_id),     CONSTRAINT FK_Transaccion_Usuario FOREIGN KEY (usuario_id)         REFERENCES Usuario(usuario_id),     CONSTRAINT CK_Transaccion_MontoPositivo CHECK (monto > 0) );  -- Crear tabla Movimiento CREATE TABLE Movimiento (     movimiento_id INT IDENTITY(1,1) NOT NULL,     cuenta_id INT NOT NULL,     transaccion_id INT NOT NULL,     monto_debito DECIMAL(18,2) DEFAULT 0,     monto_credito DECIMAL(18,2) DEFAULT 0,     saldo_resultante DECIMAL(18,2) NOT NULL,     fecha DATETIME DEFAULT GETDATE(),     CONSTRAINT PK_Movimiento PRIMARY KEY CLUSTERED (movimiento_id),     CONSTRAINT FK_Movimiento_Cuenta FOREIGN KEY (cuenta_id)         REFERENCES Cuenta(cuenta_id)         ON DELETE NO ACTION         ON UPDATE CASCADE,     CONSTRAINT FK_Movimiento_Transaccion FOREIGN KEY (transaccion_id)         REFERENCES Transaccion(transaccion_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT CK_Movimiento_MontosNoNegativos CHECK (monto_debito >= 0 AND monto_credito >= 0),     CONSTRAINT CK_Movimiento_DebitoOCredito CHECK (         (monto_debito > 0 AND monto_credito = 0) OR         (monto_debito = 0 AND monto_credito > 0)     ) );  -- Crear tabla Notificacion para seguimiento de correos CREATE TABLE Notificacion (     notificacion_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     tipo NVARCHAR(50) NOT NULL, -- 'ResumenDiario', 'AlertaSeguridad', etc.     asunto NVARCHAR(200) NOT NULL,     contenido NVARCHAR(MAX),     fecha_envio DATETIME DEFAULT GETDATE(),     estado NVARCHAR(20) DEFAULT 'Enviada', -- 'Enviada', 'Fallida', 'Pendiente'     CONSTRAINT PK_Notificacion PRIMARY KEY CLUSTERED (notificacion_id),     CONSTRAINT FK_Notificacion_Cliente FOREIGN KEY (cliente_id)         REFERENCES Cliente(cliente_id) );  --- ===================================================== --- Inserción de datos iniciales (INSERT) --- ===================================================== -- Insertar tipos de cuenta INSERT INTO TipoCuenta (nombre, descripcion) VALUES  (N'AHORRO', N'Cuenta de ahorros personal'), (N'CORRIENTE', N'Cuenta corriente personal'), (N'CREDITO', N'Tarjeta de crédito'), (N'DEBITO', N'Tarjeta de débito');  -- Insertar tipos de transacción INSERT INTO TipoTransaccion (nombre, descripcion) VALUES  (N'TRANSFER_INTERNO', N'Transferencia entre cuentas del mismo cliente'), (N'TRANSFER_EXTERNO', N'Transferencia a cuentas de otros clientes'), (N'DEPOSITO', N'Depósito de efectivo'), (N'RETIRO', N'Retiro de efectivo');  -- Insertar estados de transacción (NUEVOS VALORES) INSERT INTO EstadoTransaccion (nombre, descripcion) VALUES  ('COMPLETADO', 'Transacción completada exitosamente'), ('RECHAZADO', 'Transacción rechazada'), ('PENDIENTE', 'Transacción pendiente de procesamiento');   --- ===================================================== --- Procedimientos Almacenados (CREATE OR ALTER PROCEDURE) --- =====================================================  CREATE OR ALTER PROCEDURE sp_LoginValidate     @username NVARCHAR(50),     @password NVARCHAR(100),     @loginSuccess BIT OUTPUT,     @isLocked BIT OUTPUT,     @cliente_id INT OUTPUT,     @message NVARCHAR(100) OUTPUT,     @es_admin BIT OUTPUT AS BEGIN     DECLARE @storedHash NVARCHAR(64)     DECLARE @salt NVARCHAR(32)     DECLARE @attempts INT     DECLARE @blocked BIT          -- Se inicializan los parámetros para evitar errores     SET @loginSuccess = 0     SET @isLocked = 0     SET @cliente_id = 0     SET @message = ''          -- Validar si existe el usuario con contraseña hash y salt     SELECT          @storedHash = password_hash,          @salt = salt,          @attempts = intentos_fallidos,          @blocked = bloqueado,         @cliente_id = cliente_id,         @es_admin = es_admin     FROM Usuario      WHERE username = @username          -- Para validar si el usuario no existe     IF @storedHash IS NULL     BEGIN         SET @message = 'Usuario no encontrado'         RETURN     END          -- Validar si la cuenta está bloqueada.     IF @blocked = 1     BEGIN         SET @isLocked = 1         SET @message = 'Cuenta bloqueada. Contacte al administrador.'         RETURN     END          -- Calcula la contraseña hash con el salt (compatibilidad hex/base64)     DECLARE @inputHashBin VARBINARY(32);     DECLARE @inputHashHex NVARCHAR(64);     DECLARE @inputHashBase64 NVARCHAR(80);      SET @inputHashBin = HASHBYTES('SHA2_256', CONCAT(@password, @salt));     -- hex string (lowercase, without 0x)     SET @inputHashHex = LOWER(SUBSTRING(master.dbo.fn_varbintohexstr(@inputHashBin), 3, 8000));     -- base64 representation     SET @inputHashBase64 = CAST(N'' AS XML).value('xs:base64Binary(sql:variable("@inputHashBin"))', 'VARCHAR(80)');      -- Comparar hash: si el storedHash tiene 64 caracteres se asume hex, si no se compara con base64     IF (LEN(@storedHash) = 64)     BEGIN         IF LOWER(@storedHash) = @inputHashHex         BEGIN             -- Login exitoso             SET @loginSuccess = 1             SET @message = 'Login exitoso'                          -- Reinicia los intentos fallidos a 0 y registra la fecha del último login             UPDATE Usuario              SET intentos_fallidos = 0,                 fecha_ultimo_login = GETDATE()             WHERE username = @username         END         ELSE         BEGIN             -- Login fallido             SET @message = 'Credenciales incorrectas'                          -- Incrementar intentos fallidos             UPDATE Usuario              SET intentos_fallidos = intentos_fallidos + 1             WHERE username = @username                          -- Validar si la cuenta debería estar bloqueada             IF (SELECT intentos_fallidos FROM Usuario WHERE username = @username) >= 3             BEGIN                 UPDATE Usuario                  SET bloqueado = 1                 WHERE username = @username                                  SET @isLocked = 1                 SET @message = 'Cuenta bloqueada por demasiados intentos fallidos'             END         END     END     ELSE     BEGIN         -- tratar como base64         IF @storedHash = @inputHashBase64         BEGIN             -- Login exitoso             SET @loginSuccess = 1             SET @message = 'Login exitoso'                          -- Reinicia los intentos fallidos a 0 y registra la fecha del último login             UPDATE Usuario              SET intentos_fallidos = 0,                 fecha_ultimo_login = GETDATE()             WHERE username = @username         END         ELSE         BEGIN             -- Login fallido             SET @message = 'Credenciales incorrectas'                          -- Incrementar intentos fallidos             UPDATE Usuario              SET intentos_fallidos = intentos_fallidos + 1             WHERE username = @username                          -- Validar si la cuenta debería estar bloqueada             IF (SELECT intentos_fallidos FROM Usuario WHERE username = @username) >= 3             BEGIN                 UPDATE Usuario                  SET bloqueado = 1                 WHERE username = @username                                  SET @isLocked = 1                 SET @message = 'Cuenta bloqueada por demasiados intentos fallidos'             END         END     END END; GO  -- ================================================================================== -- Script adicional (para ejecución manual en entorno de pruebas): -- Reestablece la contraseña de todos los usuarios a 'password123', genera salt (base64) -- y almacena el hash SHA-256 como cadena hex de 64 caracteres (matching .NET ComputeSha256Hex) -- WARNING: Run only in a test environment. -- ==================================================================================  -- Example usage: execute this block to reset test passwords IF 1 = 0 BEGIN     DECLARE @pwd NVARCHAR(100) = N'password123';     DECLARE @id INT;     DECLARE @salt_bin VARBINARY(16);     DECLARE @salt_b64 NVARCHAR(80);     DECLARE @hash_bin VARBINARY(32);     DECLARE @hash_hex NVARCHAR(64);      DECLARE cur CURSOR LOCAL FAST_FORWARD FOR         SELECT usuario_id FROM Usuario;      OPEN cur;     FETCH NEXT FROM cur INTO @id;     WHILE @@FETCH_STATUS = 0     BEGIN         SET @salt_bin = CRYPT_GEN_RANDOM(16);         SET @salt_b64 = CAST(N'' AS XML).value('xs:base64Binary(sql:variable("@salt_bin"))', 'VARCHAR(80)');          SET @hash_bin = HASHBYTES('SHA2_256', CONCAT(@pwd, @salt_b64));         SET @hash_hex = LOWER(SUBSTRING(master.dbo.fn_varbintohexstr(@hash_bin), 3, 8000));          UPDATE Usuario         SET password_hash = @hash_hex,             salt = @salt_b64,             intentos_fallidos = 0,             bloqueado = 0         WHERE usuario_id = @id;          FETCH NEXT FROM cur INTO @id;     END      CLOSE cur;     DEALLOCATE cur; END  -- ================================================================================== -- Fin de script adicional -- ==================================================================================  -- Crear tabla Cliente con dirección normalizada CREATE TABLE Cliente (     cliente_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(100) NOT NULL,     email NVARCHAR(100) NOT NULL,     telefono NVARCHAR(20),     calle NVARCHAR(100),     numero NVARCHAR(20),     ciudad NVARCHAR(50),     estado_provincia NVARCHAR(50),     codigo_postal NVARCHAR(20),     pais NVARCHAR(50),     fecha_registro DATETIME DEFAULT GETDATE(),     activo BIT DEFAULT 1,     CONSTRAINT PK_Cliente PRIMARY KEY CLUSTERED (cliente_id),     CONSTRAINT UQ_Cliente_Email UNIQUE (email) );  -- Crear tabla TipoCuenta CREATE TABLE TipoCuenta (     tipo_cuenta_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(50) NOT NULL,     descripcion NVARCHAR(200),     CONSTRAINT PK_TipoCuenta PRIMARY KEY CLUSTERED (tipo_cuenta_id),     CONSTRAINT UQ_TipoCuenta_Nombre UNIQUE (nombre) );  -- Crear tabla Cuenta CREATE TABLE Cuenta (     cuenta_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     tipo_cuenta_id INT NOT NULL,     numero_cuenta NVARCHAR(20) NOT NULL,     saldo DECIMAL(18,2) NOT NULL DEFAULT 0,     fecha_apertura DATETIME DEFAULT GETDATE(),     activa BIT DEFAULT 1,     CONSTRAINT PK_Cuenta PRIMARY KEY CLUSTERED (cuenta_id),     CONSTRAINT FK_Cuenta_Cliente FOREIGN KEY (cliente_id)         REFERENCES Cliente(cliente_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT FK_Cuenta_TipoCuenta FOREIGN KEY (tipo_cuenta_id)         REFERENCES TipoCuenta(tipo_cuenta_id)         ON DELETE NO ACTION         ON UPDATE CASCADE,     CONSTRAINT UQ_Cuenta_Numero UNIQUE (numero_cuenta),     CONSTRAINT CK_Cuenta_SaldoNoNegativo CHECK (saldo >= 0) );  -- Crear tabla Usuario CREATE TABLE Usuario (     usuario_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     username NVARCHAR(50) NOT NULL,     password_hash NVARCHAR(64) NOT NULL,     salt NVARCHAR(32) NOT NULL,     intentos_fallidos INT DEFAULT 0,     bloqueado BIT DEFAULT 0,     fecha_creacion DATETIME DEFAULT GETDATE(),     fecha_ultimo_login DATETIME, 	es_admin BIT DEFAULT 0,     CONSTRAINT PK_Usuario PRIMARY KEY CLUSTERED (usuario_id),     CONSTRAINT FK_Usuario_Cliente FOREIGN KEY (cliente_id)         REFERENCES Cliente(cliente_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT UQ_Usuario_Username UNIQUE (username),     CONSTRAINT CK_Usuario_IntentosFallidos CHECK (intentos_fallidos >= 0) ); ALTER TABLE Usuario  ADD es_admin BIT DEFAULT 0;  -- Crear tabla de referencia TipoTransaccion CREATE TABLE TipoTransaccion (     tipo_transaccion_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(50) NOT NULL,     descripcion NVARCHAR(200),     CONSTRAINT PK_TipoTransaccion PRIMARY KEY CLUSTERED (tipo_transaccion_id),     CONSTRAINT UQ_TipoTransaccion_Nombre UNIQUE (nombre) );  -- Crear tabla de referencia EstadoTransaccion CREATE TABLE EstadoTransaccion (     estado_transaccion_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(20) NOT NULL,     descripcion NVARCHAR(100),     CONSTRAINT PK_EstadoTransaccion PRIMARY KEY CLUSTERED (estado_transaccion_id),     CONSTRAINT UQ_EstadoTransaccion_Nombre UNIQUE (nombre) );  -- Crear tabla Transaccion con referencias adecuadas CREATE TABLE Transaccion (     transaccion_id INT IDENTITY(1,1) NOT NULL,     tipo_transaccion_id INT NOT NULL,     estado_transaccion_id INT NOT NULL,     monto DECIMAL(18,2) NOT NULL,     descripcion NVARCHAR(200),     fecha DATETIME DEFAULT GETDATE(),     fecha_actualizacion DATETIME,     usuario_id INT, -- Quién inició la transacción 	cuenta_destino INT NULL     CONSTRAINT FK_Transaccion_CuentaDestino FOREIGN KEY (cuenta_destino) 		REFERENCES Cuenta(cuenta_id), 	cuenta_origen INT NULL     CONSTRAINT FK_Transaccion_CuentaOrigen FOREIGN KEY (cuenta_origen) 		REFERENCES Cuenta(cuenta_id),     CONSTRAINT PK_Transaccion PRIMARY KEY CLUSTERED (transaccion_id),     CONSTRAINT FK_Transaccion_TipoTransaccion FOREIGN KEY (tipo_transaccion_id)         REFERENCES TipoTransaccion(tipo_transaccion_id),     CONSTRAINT FK_Transaccion_EstadoTransaccion FOREIGN KEY (estado_transaccion_id)         REFERENCES EstadoTransaccion(estado_transaccion_id),     CONSTRAINT FK_Transaccion_Usuario FOREIGN KEY (usuario_id)         REFERENCES Usuario(usuario_id),     CONSTRAINT CK_Transaccion_MontoPositivo CHECK (monto > 0) );  -- Crear tabla Movimiento CREATE TABLE Movimiento (     movimiento_id INT IDENTITY(1,1) NOT NULL,     cuenta_id INT NOT NULL,     transaccion_id INT NOT NULL,     monto_debito DECIMAL(18,2) DEFAULT 0,     monto_credito DECIMAL(18,2) DEFAULT 0,     saldo_resultante DECIMAL(18,2) NOT NULL,     fecha DATETIME DEFAULT GETDATE(),     CONSTRAINT PK_Movimiento PRIMARY KEY CLUSTERED (movimiento_id),     CONSTRAINT FK_Movimiento_Cuenta FOREIGN KEY (cuenta_id)         REFERENCES Cuenta(cuenta_id)         ON DELETE NO ACTION         ON UPDATE CASCADE,     CONSTRAINT FK_Movimiento_Transaccion FOREIGN KEY (transaccion_id)         REFERENCES Transaccion(transaccion_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT CK_Movimiento_MontosNoNegativos CHECK (monto_debito >= 0 AND monto_credito >= 0),     CONSTRAINT CK_Movimiento_DebitoOCredito CHECK (         (monto_debito > 0 AND monto_credito = 0) OR         (monto_debito = 0 AND monto_credito > 0)     ) );  -- Crear tabla Notificacion para seguimiento de correos CREATE TABLE Notificacion (     notificacion_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     tipo NVARCHAR(50) NOT NULL, -- 'ResumenDiario', 'AlertaSeguridad', etc.     asunto NVARCHAR(200) NOT NULL,     contenido NVARCHAR(MAX),     fecha_envio DATETIME DEFAULT GETDATE(),     estado NVARCHAR(20) DEFAULT 'Enviada', -- 'Enviada', 'Fallida', 'Pendiente'     CONSTRAINT PK_Notificacion PRIMARY KEY CLUSTERED (notificacion_id),     CONSTRAINT FK_Notificacion_Cliente FOREIGN KEY (cliente_id)         REFERENCES Cliente(cliente_id) );  --- ===================================================== --- Inserción de datos iniciales (INSERT) --- ===================================================== -- Insertar tipos de cuenta INSERT INTO TipoCuenta (nombre, descripcion) VALUES  (N'AHORRO', N'Cuenta de ahorros personal'), (N'CORRIENTE', N'Cuenta corriente personal'), (N'CREDITO', N'Tarjeta de crédito'), (N'DEBITO', N'Tarjeta de débito');  -- Insertar tipos de transacción INSERT INTO TipoTransaccion (nombre, descripcion) VALUES  (N'TRANSFER_INTERNO', N'Transferencia entre cuentas del mismo cliente'), (N'TRANSFER_EXTERNO', N'Transferencia a cuentas de otros clientes'), (N'DEPOSITO', N'Depósito de efectivo'), (N'RETIRO', N'Retiro de efectivo');  -- Insertar estados de transacción (NUEVOS VALORES) INSERT INTO EstadoTransaccion (nombre, descripcion) VALUES  ('COMPLETADO', 'Transacción completada exitosamente'), ('RECHAZADO', 'Transacción rechazada'), ('PENDIENTE', 'Transacción pendiente de procesamiento');    --- ===================================================== --- Procedimientos Almacenados (CREATE OR ALTER PROCEDURE) --- =====================================================  CREATE OR ALTER PROCEDURE sp_LoginValidate     @username NVARCHAR(50),     @password NVARCHAR(100),     @loginSuccess BIT OUTPUT,     @isLocked BIT OUTPUT,     @cliente_id INT OUTPUT,     @message NVARCHAR(100) OUTPUT,     @es_admin BIT OUTPUT AS BEGIN     DECLARE @storedHash NVARCHAR(64)     DECLARE @salt NVARCHAR(32)     DECLARE @attempts INT     DECLARE @blocked BIT          -- Se inicializan los parámetros para evitar errores     SET @loginSuccess = 0     SET @isLocked = 0     SET @cliente_id = 0     SET @message = ''          -- Validar si existe el usuario con contraseña hash y salt     SELECT          @storedHash = password_hash,          @salt = salt,          @attempts = intentos_fallidos,          @blocked = bloqueado,         @cliente_id = cliente_id,         @es_admin = es_admin     FROM Usuario      WHERE username = @username          -- Para validar si el usuario no existe     IF @storedHash IS NULL     BEGIN         SET @message = 'Usuario no encontrado'         RETURN     END          -- Validar si la cuenta está bloqueada.     IF @blocked = 1     BEGIN         SET @isLocked = 1         SET @message = 'Cuenta bloqueada. Contacte al administrador.'         RETURN     END          -- Calcula la contraseña hash con el salt (compatibilidad hex/base64)     DECLARE @inputHashBin VARBINARY(32);     DECLARE @inputHashHex NVARCHAR(64);     DECLARE @inputHashBase64 NVARCHAR(80);      SET @inputHashBin = HASHBYTES('SHA2_256', CONCAT(@password, @salt));     -- hex string (lowercase, without 0x)     SET @inputHashHex = LOWER(SUBSTRING(master.dbo.fn_varbintohexstr(@inputHashBin), 3, 8000));     -- base64 representation     SET @inputHashBase64 = CAST(N'' AS XML).value('xs:base64Binary(sql:variable("@inputHashBin"))', 'VARCHAR(80)');      -- Comparar hash: si el storedHash tiene 64 caracteres se asume hex, si no se compara con base64     IF (LEN(@storedHash) = 64)     BEGIN         IF LOWER(@storedHash) = @inputHashHex         BEGIN             -- Login exitoso             SET @loginSuccess = 1             SET @message = 'Login exitoso'                          -- Reinicia los intentos fallidos a 0 y registra la fecha del último login             UPDATE Usuario              SET intentos_fallidos = 0,                 fecha_ultimo_login = GETDATE()             WHERE username = @username         END         ELSE         BEGIN             -- Login fallido             SET @message = 'Credenciales incorrectas'                          -- Incrementar intentos fallidos             UPDATE Usuario              SET intentos_fallidos = intentos_fallidos + 1             WHERE username = @username                          -- Validar si la cuenta debería estar bloqueada             IF (SELECT intentos_fallidos FROM Usuario WHERE username = @username) >= 3             BEGIN                 UPDATE Usuario                  SET bloqueado = 1                 WHERE username = @username                                  SET @isLocked = 1                 SET @message = 'Cuenta bloqueada por demasiados intentos fallidos'             END         END     END     ELSE     BEGIN         -- tratar como base64         IF @storedHash = @inputHashBase64         BEGIN             -- Login exitoso             SET @loginSuccess = 1             SET @message = 'Login exitoso'                          -- Reinicia los intentos fallidos a 0 y registra la fecha del último login             UPDATE Usuario              SET intentos_fallidos = 0,                 fecha_ultimo_login = GETDATE()             WHERE username = @username         END         ELSE         BEGIN             -- Login fallido             SET @message = 'Credenciales incorrectas'                          -- Incrementar intentos fallidos             UPDATE Usuario              SET intentos_fallidos = intentos_fallidos + 1             WHERE username = @username                          -- Validar si la cuenta debería estar bloqueada             IF (SELECT intentos_fallidos FROM Usuario WHERE username = @username) >= 3             BEGIN                 UPDATE Usuario                  SET bloqueado = 1                 WHERE username = @username                                  SET @isLocked = 1                 SET @message = 'Cuenta bloqueada por demasiados intentos fallidos'             END         END     END END; GO  -- ================================================================================== -- Script adicional (para ejecución manual en entorno de pruebas): -- Reestablece la contraseña de todos los usuarios a 'password123', genera salt (base64) -- y almacena el hash SHA-256 como cadena hex de 64 caracteres (matching .NET ComputeSha256Hex) -- WARNING: Run only in a test environment. -- ==================================================================================  -- Example usage: execute this block to reset test passwords IF 1 = 0 BEGIN     DECLARE @pwd NVARCHAR(100) = N'password123';     DECLARE @id INT;     DECLARE @salt_bin VARBINARY(16);     DECLARE @salt_b64 NVARCHAR(80);     DECLARE @hash_bin VARBINARY(32);     DECLARE @hash_hex NVARCHAR(64);      DECLARE cur CURSOR LOCAL FAST_FORWARD FOR         SELECT usuario_id FROM Usuario;      OPEN cur;     FETCH NEXT FROM cur INTO @id;     WHILE @@FETCH_STATUS = 0     BEGIN         SET @salt_bin = CRYPT_GEN_RANDOM(16);         SET @salt_b64 = CAST(N'' AS XML).value('xs:base64Binary(sql:variable("@salt_bin"))', 'VARCHAR(80)');          SET @hash_bin = HASHBYTES('SHA2_256', CONCAT(@pwd, @salt_b64));         SET @hash_hex = LOWER(SUBSTRING(master.dbo.fn_varbintohexstr(@hash_bin), 3, 8000));          UPDATE Usuario         SET password_hash = @hash_hex,             salt = @salt_b64,             intentos_fallidos = 0,             bloqueado = 0         WHERE usuario_id = @id;          FETCH NEXT FROM cur INTO @id;     END      CLOSE cur;     DEALLOCATE cur; END  -- ================================================================================== -- Fin de script adicional -- ==================================================================================  --- ===================================================== --- Consultas adicionales --- =====================================================  SELECT * FROM [dbo].[vw_MovimientosDelDia] SELECT * FROM [dbo].[vw_AnalisisTransacciones] SELECT * FROM [dbo].[vw_ResumenCliente]  --- ===================================================== --- Índices (CREATE INDEX) --- =====================================================  CREATE INDEX IX_Usuario_Username ON Usuario(username); CREATE INDEX IX_Cuenta_Cliente ON Cuenta(cliente_id); CREATE INDEX IX_Transaccion_Fecha ON Transaccion(fecha); CREATE INDEX IX_Movimiento_CuentaFecha ON Movimiento(cuenta_id, fecha);  --- ===================================================== --- Configuración de DBMail y Job de SQL Server --- =====================================================  -- Configuración de la cuenta de correo para DBMail EXECUTE msdb.dbo.sysmail_add_account_sp     @account_name = 'BancoFisclaseMail',     @description = 'Cuenta de correo para notificaciones de Banco Fisclase',     @email_address = 'andre.s.reboulet@gmail.com',     @display_name = 'Notificaciones Banco Fisclase',     @mailserver_name = 'smtp.gmail.com',     @port = 587,     @username = 'andre.s.reboulet@gmail.com',     @password = 'wzcdyrcfuohauckp',     @enable_ssl = 1;  -- Configuración del perfil de correo para DBMail EXECUTE msdb.dbo.sysmail_add_profile_sp     @profile_name = 'BancoFisclaseProfile',     @description = 'Perfil para notificaciones de Banco Fisclase';  -- Asociar la cuenta al perfil EXECUTE msdb.dbo.sysmail_add_profileaccount_sp     @profile_name = 'BancoFisclaseProfile',     @account_name = 'BancoFisclaseMail',     @sequence_number = 1;  USE msdb; GO  -- Crear el Job de SQL Server Agent EXEC msdb.dbo.sp_add_job     @job_name = 'ResumenDiarioMovimientos'; GO  -- Añadir el paso al Job para ejecutar el procedimiento de envío de resúmenes EXEC msdb.dbo.sp_add_jobstep     @job_name = 'ResumenDiarioMovimientos',     @step_name = 'EnviarResumenesClientes',     @subsystem = 'TSQL',     @command = 'EXEC BD_BancoFisclase.dbo.sp_EnviarResumenesDiarios',     @database_name = 'BD_BancoFisclase'; GO  -- Añadir la programación al Job (Diario a las 23:30) EXEC msdb.dbo.sp_add_schedule     @schedule_name = 'Diario_2330',     @freq_type = 4, -- Diario     @freq_interval = 1,     @active_start_time = 233000; -- 11:30 PM GO  -- Adjuntar la programación al Job EXEC msdb.dbo.sp_attach_schedule     @job_name = 'ResumenDiarioMovimientos',     @schedule_name = 'Diario_2330'; GO  -- Añadir el servidor al Job EXEC msdb.dbo.sp_add_jobserver     @job_name = 'ResumenDiarioMovimientos'; GO  -- Ejecutar el procedimiento de envío de resúmenes manualmente (para pruebas) EXEC sp_EnviarResumenesDiarios;  EXEC msdb.dbo.sp_start_job     @job_name = N'ResumenDiarioMovimientos'  